return ['domain'=>'zinn-backups','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'mn','project-id-version'=>'zinn-backups','pot-creation-date'=>'2026-10-08T09:17:23+00:00','po-revision-date'=>'2026-10-08T09:17:23+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Backups'=>'Zinn® Backups','https://zinndigital.com/wordpress-plugins/zinn-backups'=>'https://zinndigital.com/wordpress-plugins/zinn-backups','Backs up your WordPress files and database to your own storage — Dropbox, Google Drive, Cloudflare R2, Amazon S3 or any S3-compatible bucket — restores them in one go, and imports backups made by other backup and migration plugins.'=>'Таны WordPress файлууд болон мэдээллийн санг өөрийн хадгалах сан болох Dropbox, Google Drive, Cloudflare R2, Amazon S3 эсвэл S3-тэй нийцтэй дурын санд нөөцөлж, тэдгээрийг нэгэн зэрэг сэргээж, бусад нөөцлөлт болон шилжүүлгийн нэмэлт өргөтгөлүүдийн үүсгэсэн нөөцлөлтийг импортлоно.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Backups'=>'Нөөцлөлтүүд','Get Pro: schedules, several storages, encryption'=>'Pro хувилбарыг авах: хуваарь, олон хадгалах сан, шифрлэлт','Working…'=>'Ажиллаж байна…','Finished'=>'Дууссан','Failed'=>'Амжилтгүй болсон','Cancelled'=>'Цуцлагдсан','Cancel'=>'Цуцлах','Restore'=>'Сэргээх','Delete'=>'Устгах','Delete this backup from your storage? This cannot be undone.'=>'Энэ нөөц хуулбарыг өөрийн сангаас устгах уу? Үүнийг буцаах боломжгүй.','No backups yet. Press “Back up now” to make the first one.'=>'Одоогоор нөөц хуулбар алга байна. Эхнийхийг үүсгэхийн тулд "Одоо нөөцлөх" дээр дарна уу.','Reading your storage…'=>'Таны хадгалах санг уншиж байна…','a complete backup, as opposed to an incremental oneFull backup'=>'Бүрэн нөөцлөлт','a backup holding only what changed since an earlier oneIncremental backup'=>'Өсөн нэмэгдэх нөөцлөлт','Encrypted'=>'Шифрлэгдсэн','From another site'=>'Өөр сайтаас','Database'=>'Өгөгдлийн сан','Files'=>'Файлууд','Uploading %1$s: %2$s%%'=>'%1$s-г хуулж байна: %2$s%%','Sign in to Dropbox in the window that opened, then paste the code Dropbox shows you:'=>'Нээгдсэн цонхонд Dropbox-д нэвтэрч, Dropbox-оос харуулсан кодыг буулгана уу:','Saved.'=>'Хадгалсан.','Remove this destination from the plugin? The backups stored in it are not deleted.'=>'Энэ байршлыг залгаасаас хасах уу? Үүнд хадгалагдсан нөөц хуулбарууд устахгүй.','Reload the page to see the restored site.'=>'Сэргээсэн сайтыг харахын тулд хуудсыг дахин ачаална уу.','Storage'=>'Хадгалах сан','Import & migrate'=>'Импортлох ба шилжүүлэх','Settings'=>'Тохиргоо','Sections'=>'Хэсгүүд','Google Drive is connected.'=>'Google Drive холбогдсон байна.','Google Drive could not be connected.'=>'Google Drive-г холбох боломжгүй байна.','Details'=>'Дэлгэрэнгүй','Back up now'=>'Одоо нөөцлөх','Backups go to your own storage, not this server. <a href="%s">Connect your storage</a> first.'=>'Нөөцлөлтүүд энэ серверт биш, таны өөрийн хадгалах санд хадгалагдана. Эхлээд <a href="%s">хадгалах сангаа холбоно уу</a>.','What to back up'=>'Юуны нөөц хуулбар хийх вэ','Files and database'=>'Файлууд болон өгөгдлийн сан','Database only'=>'Зөвхөн өгөгдлийн сан','Files only'=>'Зөвхөн файлууд','Note (optional)'=>'Тэмдэглэл (заавал биш)','Each part is uploaded to your storage and removed from this server before the next one is made, so the backup never takes up room on your hosting.'=>'Дараагийн хэсгийг үүсгэхээс өмнө хэсэг бүрийг таны хадгалах сан руу байршуулж, энэ серверээс устгадаг тул нөөц хуулбар нь таны хостинг дээр хэзээ ч зай эзэлдэггүй.','Your backups'=>'Таны нөөцлөлтүүд','Refresh'=>'Сэргээх','Restore this backup'=>'Энэ нөөц хуулбарыг сэргээх','Passphrase'=>'Нууц хэллэг','I understand this replaces this site’s files and database with the backup’s. Files that are not in the backup are kept.'=>'Энэ нь энэ сайтын файлууд болон өгөгдлийн санг нөөцлөлтөөр солино гэдгийг ойлгож байна. Нөөцлөлтөд ороогүй файлууд хадгалагдана.','Recent activity'=>'Сүүлийн үеийн үйл ажиллагаа','Backup'=>'Нөөцлөлт','Restore / import'=>'Сэргээх / импортлох','Running'=>'Ажиллаж байна','Your storage'=>'Таны хадгалах сан' . "\0" . 'Таны хадгалах байршлууд','No storage yet. Choose where your backups go below.'=>'Хараахан хадгалах сан байхгүй байна. Таны нөөцлөлтүүд хаашаа орохыг доороос сонгоно уу.','Ready'=>'Бэлэн','Not connected'=>'Холбогдоогүй','Connect'=>'Холбох','Test'=>'Туршилт','Edit'=>'Засах','Remove'=>'Устгах','Add storage'=>'Хадгалах зай нэмэх','Backups go to one storage destination. To use a different one, edit or remove the one above.'=>'Нөөцлөлтүүд нэг хадгалах байршил руу очно. Өөр байршил ашиглахын тулд дээрхийг засна уу эсвэл устгана уу.','Kind of storage'=>'Хадгалах сангийн төрөл','Name (for you)'=>'Нэр (таны хувьд)','Provider'=>'Нийлүүлэгч','Cloudflare account id'=>'Cloudflare дансны ID','Endpoint address'=>'Төгсгөлийн цэгийн хаяг','Region'=>'Бүс','Bucket'=>'Бакет','Access key id'=>'Хандах түлхүүрийн ID','Secret access key'=>'Нууц хандалтын түлхүүр','Leave empty to keep the saved key'=>'Хадгалсан түлхүүрийг хэвээр үлдээхийн тулд хоосон орхино уу','For Cloudflare R2: in the Cloudflare dashboard open R2, create a bucket, then “Manage R2 API tokens” → create a token with Object Read & Write for that bucket, and copy the access key id and secret here.'=>'Cloudflare R2-ийн хувьд: Cloudflare хянах самбарт R2-ийг нээж, bucket үүсгээд, дараа нь “Manage R2 API tokens” → тухайн bucket-д зориулж Object Read & Write эрхтэй токен үүсгэж, access key id болон secret-ийг энд хуулна уу.','Dropbox app key'=>'Dropbox аппын түлхүүр','Create an app at dropbox.com/developers/apps (Scoped access, App folder) with the files.content.read, files.content.write and files.metadata.read permissions, and copy its App key here. Save, then press Connect.'=>'dropbox.com/developers/apps дээр files.content.read, files.content.write болон files.metadata.read зөвшөөрөлтэй апп үүсгэж (Scoped access, App folder), түүний App key-г энд хуулна уу. Хадгалаад, дараа нь Connect дээр дарна уу.','OAuth client id'=>'OAuth клиентийн ID','OAuth client secret'=>'OAuth клиентийн нууц','Leave empty to keep the saved secret'=>'Хадгалсан нууцыг хэвээр үлдээхийн тулд хоосон орхино уу','In Google Cloud Console, enable the Google Drive API, then create an OAuth client of type “Web application” with this address as an authorised redirect URI:'=>'Google Cloud Console дотор Google Drive API-г идэвхжүүлж, дараа нь энэ хаягийг зөвшөөрөгдсөн дахин чиглүүлэх URI болгон ашиглан "Web application" төрлийн OAuth клиент үүсгэнэ үү:','Save, then press Connect. The plugin only sees the files it creates.'=>'Хадгалаад, дараа нь Холбох товчийг дарна уу. Залгаас нь зөвхөн өөрийн үүсгэсэн файлуудыг л харна.','Folder inside the storage (optional)'=>'Хадгалах сан доторх хавтас (заавал биш)','Save storage'=>'Хадгалах зай хэмнэх','Import a backup from another plugin or host'=>'Өөр нэмэлт өргөтгөл эсвэл хостоос нөөцлөлт импортлох','Bring a site in from a backup made by UpdraftPlus, All-in-One WP Migration (.wpress), Duplicator (zip), BackWPup, WPvivid, Jetpack VaultPress Backup, BlogVault, Zinn® Migrate, or any zip/tar archive of a WordPress site with its .sql dump. The content goes into wp-content and the database replaces this site’s; addresses are changed to this site’s automatically.'=>'UpdraftPlus, All-in-One WP Migration (.wpress), Duplicator (zip), BackWPup, WPvivid, Jetpack VaultPress Backup, BlogVault, Zinn® Migrate эсвэл .sql дамп бүхий WordPress сайтын дурын zip/tar архиваас үүсгэсэн нөөц хуулбараас сайтыг оруулж ирнэ үү. Агуулга нь wp-content руу очих бөгөөд өгөгдлийн сан нь энэ сайтынхыг орлох болно; хаягууд автоматаар энэ сайтын хаяг болж өөрчлөгдөнө.','Upload from your computer'=>'Компьютерээсээ байршуулах','Choose every file of the backup at once (UpdraftPlus makes several). Large files are sent in small pieces, so your host’s upload limit does not apply.'=>'Нөөц хуулбарын файл бүрийг нэгэн зэрэг сонгоно уу (UpdraftPlus хэд хэдэн файл үүсгэдэг). Том файлуудыг жижиг хэсгүүдээр илгээдэг тул таны хостын хуулах хязгаар хамаарахгүй.','Or from links (Google Drive, Dropbox or any download address)'=>'Эсвэл холбоосоос (Google Drive, Dropbox эсвэл татаж авах дурын хаяг)','One link per line. For Google Drive and Dropbox, share the file with “anyone with the link” and paste that link; turn sharing off again afterwards.'=>'Мөр тус бүрд нэг холбоос. Google Drive болон Dropbox-ын хувьд файлыг "холбоос бүхий хэн ч байсан" гэж хуваалцаад уг холбоосыг буулгана уу; дараа нь хуваалцахыг дахин унтраана уу.','Or a file already on this server'=>'Эсвэл энэ сервер дээр аль хэдийн байгаа файл','Upload archives by FTP or your host’s file manager into %s and reload this page.'=>'Архивуудыг FTP эсвэл өөрийн хостын файл менежерээр %s руу хуулж, энэ хуудсыг дахин ачаална уу.','Or a deploy code from another site'=>'Эсвэл өөр сайтаас байршуулах код','If another site gave you a Zinn® Backups deploy code, paste it here to copy that backup onto this site without sharing its storage keys. A code works for a few hours; treat it like a password.'=>'Хэрэв өөр сайт танд Zinn® Backups-ийн байршуулах код өгсөн бол түүний хадгалах сангийн түлхүүрүүдийг хуваалцахгүйгээр уг нөөц хуулбарыг энэ сайт руу хуулахын тулд энд буулгана уу. Код нь хэдхэн цагийн турш ажиллах тул үүнийг нууц үг шиг авч үзнэ үү.','Passphrase (only if that backup is encrypted)'=>'Нууц хэллэг (зөвхөн тэрхүү нөөцлөлт шифрлэгдсэн бол)','Import'=>'Импортлох','I understand the import replaces this site’s content and database. After it, sign in with an account from the imported site.'=>'Импорт нь энэ сайтын агуулга болон мэдээллийн санг орлоно гэдгийг ойлгож байна. Үүний дараа импортлосон сайтын бүртгэлээр нэвтэрнэ үү.','Moving to Zinn® hosting?'=>'Zinn® хостинг руу шилжих үү?','Zinn Digital® can move your site for you from your old host. If your old host gives you no FTP, SSH or control-panel access, install Zinn® Migrate on the old site; it makes one archive you can import here or hand to Zinn®.'=>'Zinn Digital® нь таны хуучин хостоос сайтыг тань таны өмнөөс шилжүүлж өгөх боломжтой. Хэрэв таны хуучин хост танд FTP, SSH эсвэл хяналтын самбарын хандалт өгөхгүй бол хуучин сайт дээр Zinn® Migrate-ийг суулгана уу; энэ нь таны энд импортлох эсвэл Zinn®-д өгөх боломжтой нэг архивыг үүсгэдэг.','What goes into a backup'=>'Нөөцлөлтөд юу багтдаг вэ','Include WordPress’s own files (wp-admin, wp-includes). Usually not needed: WordPress can always be reinstalled.'=>'WordPress-ийн өөрийн файлуудыг оруулах (wp-admin, wp-includes). Ихэвчлэн шаардлагагүй: WordPress-ийг хэзээ ч дахин суулгах боломжтой.','Also leave out these folders or files (one per line, relative to the WordPress folder)'=>'Мөн эдгээр хавтас эсвэл файлуудыг орхино уу (мөр бүрт нэг, WordPress хавтастай харьцангуй)','Always left out: caches, update scratch space, and other backup plugins’ own archive folders:'=>'Үргэлж хасагдах: кэшүүд, шинэчлэлтийн түр зай болон бусад нөөцлөх залгаасуудын өөрийн архивын хавтаснууд:','Size of each part (MB)'=>'Хэсэг тус бүрийн хэмжээ (МБ)','Save settings'=>'Тохиргоог хадгалах','A backup part could not be opened for writing. Check that wp-content has free space.'=>'Нөөцлөлтийн хэсгийг бичихэд нээж чадсангүй. wp-content дотор сул зай байгаа эсэхийг шалгана уу.','A backup part could not be written. Check that wp-content has free space.'=>'Нөөцлөлтийн хэсгийг бичиж чадсангүй. wp-content дээр сул зай байгаа эсэхийг шалгана уу.','Connect a storage destination on the Storage tab first: backups are kept in your own storage, not on this server.'=>'Эхлээд Storage таб дээр хадгалах байршлыг холбоно уу: нөөц хуулбарууд энэ сервер дээр бус, таны өөрийн хадгалах санд хадгалагдана.','Multisite networks are not supported yet.'=>'Олон сайтын сүлжээг хараахан дэмжихгүй байна.','This server’s PHP has no ZipArchive extension. Ask your host to enable it.'=>'Энэ серверийн PHP-д ZipArchive өргөтгөл алга байна. Үүнийг идэвхжүүлэхийг хостинг үйлчилгээ үзүүлэгчээсээ хүснэ үү.','Starting'=>'Эхлүүлж байна','Listing files'=>'Файлуудыг жагсааж байна','Backing up the database'=>'Өгөгдлийн сангийн нөөц хуулбар хийж байна','Packing files'=>'Файлуудыг багцалж байна','Uploading to your storage'=>'Таны хадгалах сан руу хуулж байна','Finishing'=>'Дуусгаж байна','The backup reached an unknown stage.'=>'Нөөцлөлт тодорхойгүй үе шатанд хүрсэн байна.','Backup %s started.'=>'%s-н нөөцлөлт эхэллээ.','Found %1$s files (%2$s).'=>'%1$s файл олдлоо (%2$s).','Database: %1$d tables, %2$s rows, %3$s compressed.'=>'Өгөгдлийн сан: %1$d хүснэгт, %2$s мөр, %3$s шахагдсан.','Backup complete: %1$s stored in %2$d destination.'=>'Нөөцлөлт дууссан: %1$s-г %2$d байршилд хадгалсан.' . "\0" . 'Нөөцлөлт дууссан: %1$s-г %2$d газарт хадгаллаа.','Some parts already uploaded could not be removed from your storage; they are in an incomplete backup folder and are never offered for restore.'=>'Аль хэдийн байршуулсан зарим хэсгийг таны хадгалах сангаас устгах боломжгүй байв; тэдгээр нь дутуу нөөцлөлтийн хавтсанд байгаа бөгөөд сэргээхэд хэзээ ч санал болгогдохгүй.','A storage destination was removed while the backup was running.'=>'Нөөцлөлт хийгдэж байх үед хадгалах байршил устгагдсан байна.','That is not a backup folder.'=>'Энэ нь нөөцлөлтийн хавтас биш байна.','That storage destination is no longer saved on this site.'=>'Энэ хадгалах байршил энэ сайтад хадгалагдахаа больсон байна.','Later incremental backups are built on this one. Delete those first.'=>'Дараагийн өсөн нэмэгдэх нөөц хуулбарууд нь үүн дээр үндэслэгдсэн байна. Эхлээд тэдгээрийг устгана уу.','This file is not an encrypted Zinn® Backups file.'=>'Энэ файл нь шифрлэгдсэн Zinn® Backups файл биш байна.','The backup could not be decrypted: the passphrase is wrong or the file is damaged.'=>'Нөөц хуулбарын шифрийг тайлж чадсангүй: нууц үг буруу эсвэл файл гэмтсэн байна.','The encrypted backup file is incomplete.'=>'Шифрлэгдсэн нөөц хуулбарын файл дутуу байна.','The database file could not be written. Check that wp-content has free space.'=>'Өгөгдлийн сангийн файлыг бичиж чадсангүй. wp-content дотор сул зай байгаа эсэхийг шалгана уу.','That is not a deploy code. A deploy code starts with zbdeploy1.'=>'Энэ байршуулах код биш байна. Байршуулах код zbdeploy1-ээр эхэлдэг.','That deploy code is damaged. Copy it again from the other site.'=>'Байршуулах код гэмтсэн байна. Үүнийг нөгөө сайтаас дахин хуулна уу.','The deploy code has expired or its backup was deleted. Make a new code on the other site.'=>'Байршуулах кодын хугацаа дууссан эсвэл нөөц хуулбар нь устгагдсан байна. Нөгөө сайт дээр шинэ код үүсгэнэ үү.','That deploy code does not point at a Zinn® Backups backup.'=>'Тэрхүү байршуулах код нь Zinn® Backups нөөц хуулбар руу заагаагүй байна.','The deploy code has expired. Make a new code on the other site.'=>'Байршуулах кодын хугацаа дууссан байна. Нөгөө сайт дээр шинэ код үүсгэнэ үү.','The server stopped honouring partial downloads. Start the import again.'=>'Сервер хэсэгчлэн татах үйлдлийг дэмжихээ больсон байна. Импортыг дахин эхлүүлнэ үү.','The link opened a web page instead of a file. For Google Drive and Dropbox, share the file with “anyone with the link” and paste that link.'=>'Холбоос нь файлын оронд вэб хуудсыг нээсэн байна. Google Drive болон Dropbox-ын хувьд файлыг "холбоос бүхий хүн бүр" тохиргоотойгоор хуваалцаж, тухайн холбоосыг буулгана уу.','The link answered with HTTP %d.'=>'Холбоос HTTP %d хариу өглөө.','The file list could not be written.'=>'Файлын жагсаалтыг бичиж чадсангүй.','The storage service could not be reached: %s'=>'Хадгалах сангийн үйлчилгээтэй холбогдож чадсангүй: %s','%1$s answered with HTTP %2$d: %3$s'=>'%1$s дараах HTTP %2$d кодоор хариулав: %3$s','no details given'=>'Дэлгэрэнгүй мэдээлэл өгөгдөөгүй байна','You are not allowed to manage backups.'=>'Та нөөц хуулбарыг удирдах эрхгүй байна.','Tick the box to confirm that the restore replaces this site’s files and database.'=>'Сэргээлт нь энэ сайтын файл болон мэдээллийн санг солихыг баталгаажуулахын тулд нүдийг чагтална уу.','Save the destination first.'=>'Эхлээд очих газрыг хадгална уу.','Connected: a test file was written and removed.'=>'Холбогдсон: тестийн файл бичигдэж, устгагдсан.','Enter the app key of your Dropbox app first (see the steps beside the form).'=>'Эхлээд өөрийн Dropbox аппын апп түлхүүрийг оруулна уу (маягтын хажууд байгаа алхмуудыг харна уу).','This kind of storage does not sign in.'=>'Энэ төрлийн хадгалах сан системд нэвтэрдэггүй.','The sign-in expired. Press Connect again.'=>'Нэвтрэх хугацаа дууссан байна. Холбох товчийг дахин дарна уу.','Dropbox is connected.'=>'Dropbox холбогдсон.','Settings saved.'=>'Тохиргоо хадгалагдлаа.','Another backup, restore or import is running. Wait for it to finish, or cancel it.'=>'Өөр нөөцлөлт, сэргээлт эсвэл импорт хийгдэж байна. Үүнийг дуустал хүлээнэ үү, эсвэл цуцална уу.','The upload was not started properly. Start again.'=>'Хуулалт зөв эхэлсэнгүй. Дахин эхлүүлнэ үү.','The chunk did not arrive. Your server may limit upload sizes; try again.'=>'Хэсэг ирсэнгүй. Таны сервер байршуулах хэмжээг хязгаарласан байж магадгүй; дахин оролдоно уу.','Tick the box to confirm that the import replaces this site’s content and database.'=>'Импорт нь энэ сайтын агуулга болон мэдээллийн санг орлох болно гэдгийг баталгаажуулахын тулд нүдийг чагтална уу.','Choose an archive to import: upload it, paste a link, or pick one from the import folder.'=>'Импортлох архивыг сонгоно уу: байршуулах, холбоос буулгах, эсвэл импортын хавтаснаас нэгийг сонгоно уу.','Hosting customer? Get %1$d%% off %2$s'=>'Хостингийн хэрэглэгч үү? %2$s дээр %1$d%% хөнгөлөлт аваарай','As a Zinn Digital® hosting customer you get a personal code for %d%% off your first payment. Renewals are at the normal price.'=>'Zinn Digital® хостингийн хэрэглэгчийн хувьд та анхны төлбөрөөсөө %d%% хөнгөлөлт авах хувийн код авах болно. Сунгалтыг ердийн үнээр хийнэ.','Get my %d%% code and go to checkout'=>'Миний %d%% кодыг авч тооцоо хийх хэсэг рүү очно уу','Sorry, you are not allowed to do that.'=>'Уучлаарай, танд үүнийг хийх эрх олгогдоогүй байна.','This discount is for customers with a paid hosting plan in good standing. Free trials do not qualify.'=>'Энэхүү хөнгөлөлт нь төлбөрийн зөрчилгүй, төлбөртэй хостингийн багцтай хэрэглэгчдэд зориулагдсан болно. Үнэгүй туршилтын хувилбарууд хамаарахгүй.','You have already used your hosting-customer discount for this plugin.'=>'Та энэ залгаасын хостинг хэрэглэгчийн хөнгөлөлтөө аль хэдийн ашигласан байна.','We could not get your code just now. Please try again in a few minutes.'=>'Бид таны кодыг сая авч чадсангүй. Хэдэн минутын дараа дахин оролдоно уу.','Reading the backup'=>'Нөөц хуулбарыг уншиж байна','Downloading the archive'=>'Архивыг татаж авч байна','Recognising the archive'=>'Архивыг таньж байна','Restoring files'=>'Файлуудыг сэргээж байна','Downloading the database'=>'Өгөгдлийн санг татаж байна','Restoring the database'=>'Өгөгдлийн санг сэргээж байна','Updating the site address'=>'Сайтын хаягийг шинэчилж байна','Switching to the restored database'=>'Сэргээсэн өгөгдлийн сан руу шилжиж байна','The restore reached an unknown stage.'=>'Сэргээлт тодорхойгүй үе шатанд хүрсэн байна.','This folder has no complete Zinn® Backups backup in it (the manifest is missing).'=>'Энэ хавтсанд бүрэн Zinn® Backups нөөц хуулбар байхгүй байна (манифест дутуу байна).','This backup is encrypted. Enter its passphrase to restore it.'=>'Энэ нөөцлөлт шифрлэгдсэн байна. Үүнийг сэргээхийн тулд нууц үгээ оруулна уу.','This incremental backup needs backup %s, which is no longer in the storage.'=>'Энэхүү өсөн нэмэгдэх нөөц хуулбарт хадгалах санд байхаа больсон %s нөөц хуулбар шаардлагатай.','Restoring the backup of %1$s (%2$d file parts).'=>'%1$s-ийн нөөц хуулбарыг сэргээж байна (%2$d файлын хэсэг).','%1$s file could not be overwritten because this site is not allowed to change it, and was left as it is: %2$s'=>'%1$s файлыг дарж бичих боломжгүй байв, учир нь энэ сайт үүнийг өөрчлөх эрхгүй тул хэвээр нь үлдээсэн: %2$s' . "\0" . 'Энэ сайт тэдгээрийг өөрчлөх эрхгүй тул %1$s файлыг дарж бичих боломжгүй байсан бөгөөд хэвээр нь үлдээсэн: %2$s','Restored %s files.'=>'%s файл сэргээгдсэн.','%s did not match its checksum after downloading. The copy in storage may be damaged.'=>'%s нь татаж авсны дараа шалгах нийлбэртэйгээ таарсангүй. Хадгалах санд байгаа хуулбар гэмтсэн байж болзошгүй.','%s did not arrive. Upload it again.'=>'%s ирсэнгүй. Үүнийг дахин байршуулна уу.','Recognised: %s.'=>'Танигдсан: %s.','Imported %1$s files into wp-content (%2$s left out: caches, drop-ins and other backup plugins’ folders).'=>'wp-content руу %1$s файл импортлосон (%2$s-г орхисон: кэшүүд, drop-in-ууд болон бусад нөөцлөх залгаасуудын хавтаснууд).','The archive has no database dump, so only files were imported.'=>'Архивт өгөгдлийн сангийн хуулбар байхгүй тул зөвхөн файлуудыг импортолсон.','Database restored into %d temporary tables.'=>'Өгөгдлийн санг %d түр хүснэгтэд сэргээсэн.','%s has no WordPress tables in it and was skipped.'=>'%s нь дотроо ямар ч WordPress хүснэгт агуулаагүй тул алгаслаа.','The backup’s database has no WordPress tables, so nothing was replaced.'=>'Нөөцлөлтийн өгөгдлийн санд WordPress хүснэгтүүд байхгүй тул юу ч солигдоогүй.','This backup is of a multisite network. Restoring a network into a single site is not supported.'=>'Энэхүү нөөц хуулбар нь сүлжээ сайтынх (multisite) юм. Сүлжээг нэг сайтад сэргээхийг дэмжихгүй.','Moving the content from %1$s to %2$s.'=>'Агуулгыг %1$s-ээс %2$s руу зөөж байна.','Restore complete. If you are signed out, sign in with an account from the restored site.'=>'Сэргээж дууслаа. Хэрэв та системээс гарсан бол сэргээсэн сайтын бүртгэлээр нэвтэрнэ үү.','Restore complete.'=>'Сэргээж дууслаа.','%1$s — trying again in %2$d seconds.'=>'%1$s — %2$d секундийн дараа дахин оролдоно.','Cancelled.'=>'Цуцлагдсан.','Backups go to one storage destination. Edit or remove the one you have to use a different one.'=>'Нөөцлөлтүүд нэг хадгалах байршил руу очно. Өөр байршил ашиглахын тулд байгаагаа засах эсвэл устгана уу.','The database file could not be opened.'=>'Өгөгдлийн сангийн файлыг нээж чадсангүй.','The database refused a statement from the backup: %1$s (%2$s…)'=>'Өгөгдлийн сан нөөцлөлтөөс ирсэн мэдэгдлийг буцаалаа: %1$s (%2$s…)','The restored tables could not be swapped in: %s. Your site is unchanged.'=>'Сэргээсэн хүснэгтүүдийг сэлгэж чадсангүй: %s. Таны сайт өөрчлөгдөөгүй хэвээр байна.','There is no writable folder for temporary backup files. Make wp-content writable and try again.'=>'Түр нөөц файлуудад зориулсан бичих боломжтой хавтас байхгүй байна. wp-content хавтсыг бичих боломжтой болгоод дахин оролдоно уу.','Could not create a folder for this job.'=>'Энэ даалгаварт зориулж хавтас үүсгэж чадсангүй.','%s — guides and services'=>'%s — гарын авлага ба үйлчилгээ','User guides'=>'Хэрэглэгчийн гарын авлага','Read the %s user guide'=>'%s хэрэглэгчийн гарын авлагыг уншина уу','Hide this'=>'Үүнийг нуух','Zinn® hosting for WordPress'=>'WordPress-д зориулсан Zinn® хостинг','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, өдөр тутмын нөөцлөлт, үнэгүй шилжүүлэг болон нэгээс олон сайт ажиллуулдаг хүмүүст зориулсан хяналтын самбар.','The Zinn® marketplace'=>'Zinn® зах зээл','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'Хоёр тал сэтгэл хангалуун байх хүртэл мөнгийг найдвартай хадгалж, хөгжүүлсэн сайтууд, домэйнууд болон холбоос байршуулалтуудыг худалдан авч, зарна уу.','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — үүнийг мэргэжлийн түвшинд хийдэг хүмүүсийг хөлслөөрэй','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'Манай дэлхийн чөлөөт зах зээл: зохиолчид, дизайнерууд, хөгжүүлэгчид болон SEO мэргэжилтнүүдийн 10,000 гаруй бэлэн үйлчилгээтэй танилцах эсвэл төсөл нийтэлж санал ирүүлэх боломжийг тэдэнд олгоно уу.','See the Zinn Digital® release notes.'=>'Zinn Digital® хувилбарын тэмдэглэлийг үзнэ үү.','The Zinn® update service did not issue a download link for this update. Check that this site can reach the Zinn® platform, then try again.'=>'Zinn® шинэчлэлийн үйлчилгээ энэ шинэчлэлтийн татах холбоосыг олгосонгүй. Энэ сайт Zinn® платформд холбогдож чадах эсэхийг шалгаад, дахин оролдоно уу.','The update could not be downloaded from the Zinn® update service (%s). Try again in a few minutes.'=>'Zinn® шинэчлэх үйлчилгээнээс (%s) шинэчлэлтийг татаж авах боломжгүй байна. Хэдэн минутын дараа дахин оролдоно уу.','The downloaded update failed its integrity check and was not installed.'=>'Татаж авсан шинэчлэлтийн бүрэн бүтэн байдлыг шалгах ажиллагаа амжилтгүй болсон тул суулгасангүй.','The zip archive could not be opened. It may be damaged or incomplete.'=>'Zip архивыг нээх боломжгүй байна. Энэ нь гэмтсэн эсвэл дутуу байж магадгүй.','This .wpress file uses a format we cannot read (it may be compressed or encrypted by All-in-One WP Migration). Export it again without encryption.'=>'Энэхүү .wpress файл нь бидний унших боломжгүй форматыг ашиглаж байна (үүнийг All-in-One WP Migration ша шахсан эсвэл шифрлэсэн байж болзошгүй). Үүнийг шифрлэлтгүйгээр дахин экспортлоно уу.','This is a Duplicator “DupArchive” (.daf) file. In Duplicator, build the package again with the archive format set to ZIP, then import that.'=>'Энэ бол Duplicator “DupArchive” (.daf) файл юм. Duplicator дотор архивын форматыг ZIP болгон тохируулан багцыг дахин үүсгэж, дараа нь импортлоно уу.','This UpdraftPlus database backup is encrypted. Decrypt it in UpdraftPlus (or turn off database encryption and back up again), then import it.'=>'Энэхүү UpdraftPlus өгөгдлийн сангийн нөөцлөлт нь шифрлэгдсэн байна. Үүнийг UpdraftPlus дээр тайлна уу (эсвэл өгөгдлийн сангийн шифрлэлтийг унтрааж, дахин нөөцөлнө үү), дараа нь импортлоно уу.','Database dump'=>'Өгөгдлийн сангийн дамп','%s is not a backup archive we can read (zip, tar, tar.gz, .wpress, .sql or .sql.gz).'=>'%s нь бидний уншиж чадах нөөц архив биш байна (zip, tar, tar.gz, .wpress, .sql эсвэл .sql.gz).','Website archive'=>'Вэбсайтын архив','%s has no WordPress content (no wp-content folder and no database dump) in it.'=>'%s нь дотроо ямар ч WordPress агуулга (wp-content хавтас болон өгөгдлийн сангийн хуулбар байхгүй) агуулаагүй байна.','This .wpress file is encrypted or compressed by All-in-One WP Migration. Export it again with encryption and compression switched off, then import that.'=>'Энэхүү .wpress файл нь All-in-One WP Migration-аар шифрлэгдсэн эсвэл шахагдсан байна. Шифрлэлт болон шахалтыг унтрааж дахин экспортлоод, дараа нь импортлоно уу.','Other S3-compatible storage'=>'Бусад S3-тэй нийцтэй сан','Cloudflare R2, Amazon S3 or S3-compatible'=>'Cloudflare R2, Amazon S3 эсвэл S3-д нийцтэй','The storage keys could not be read on this site. Enter the secret key again on the Storage tab.'=>'Энэ сайт дээр хадгалах сангийн түлхүүрүүдийг унших боломжгүй байлаа. Хадгалах сан таб дээр нууц түлхүүрийг дахин оруулна уу.','This kind of storage is not known.'=>'Энэ төрлийн хадгалах сан тодорхойгүй байна.','Choose a kind of storage.'=>'Хадгалах сангийн төрлийг сонгоно уу.','Enter the bucket name and the access key.'=>'Бакетын нэр болон хандалтын түлхүүрийг оруулна уу.','Enter your Cloudflare account id (or the full R2 endpoint).'=>'Өөрийн Cloudflare бүртгэлийн ID-г (эсвэл бүтэн R2 төгсгөлийн цэгийг) оруулна уу.','Enter the endpoint address of your storage.'=>'Хадгалах сангийнхаа төгсгөлийн цэгийн хаягийг оруулна уу.','Enter the OAuth client id from your Google Cloud project.'=>'Та Google Cloud төслөөсөө OAuth client id-г оруулна уу.','Dropbox did not return a refresh token. Start the connection again.'=>'Dropbox сэргээх токен буцаасангүй. Холболтыг дахин эхлүүлнэ үү.','Dropbox is not connected. Connect it again on the Storage tab.'=>'Dropbox холбогдоогүй байна. Хадгалах сан таб дээр дахин холбоно уу.','Google did not return a refresh token. Remove this site from your Google account’s third-party access and connect again.'=>'Google сэргээх токен буцаасангүй. Энэ сайтыг өөрийн Google бүртгэлийн гуравдагч талын хандалтаас хасаад дахин холбогдоно уу.','That file is not in Google Drive any more.'=>'Тэр файл Google Drive дээр байхаа больсон байна.','Google Drive is not connected. Connect it again on the Storage tab.'=>'Google Drive холбогдоогүй байна. Сангийн таб дээр дахин холбоно уу.','The storage service did not start the upload.'=>'Хадгалах үйлчилгээ байршуулалтыг эхлүүлсэнгүй.','The storage service sent a reply that could not be read.'=>'Хадгалах үйлчилгээ унших боломжгүй хариу илгээлээ.','A temporary backup file could not be read.'=>'Түр нөөц файлыг уншиж чадсангүй.','A deploy link is read-only.'=>'Байршуулалтын холбоос нь зөвхөн унших боломжтой.','The deploy code has no link for a file this backup needs.'=>'Байршуулах кодонд энэ нөөц хуулбарт шаардлагатай файлын холбоос байхгүй байна.','The deploy link'=>'Байршуулах холбоос']];